class Solution {
  public double probabilityOfHeads(double[] prob, int target) {
    double[] dp = new double[target + 1]; // dp[h]: probability of exactly h heads so far
    dp[0] = 1;
    for (double p : prob)
      for (int h = target; h >= 0; h--) dp[h] = dp[h] * (1 - p) + (h > 0 ? dp[h - 1] * p : 0);
    return dp[target];
  }
}
